#!/usr/bin/env node
/**
 * Builds a tiny, 100% original NES ROM used to smoke-test the emulator. No
 * copyrighted game data is involved: the program is assembled from the source
 * below and the font tiles are generated by tools/font8x8.mjs.
 *
 *   PRG  32 KiB, NROM-256 (mapper 0), CHR-RAM (8 KiB), horizontal mirroring
 *
 * The program:
 *   1. standard reset sequence (APU IRQ off, stack, PPU off, clear RAM),
 *   2. waits for two vblanks,
 *   3. uploads the 8 KiB font into CHR-RAM through $2007,
 *   4. clears nametable 0 and writes two lines of text,
 *   5. sets a palette where text is white on black,
 *   6. enables background rendering and increments $10 every frame.
 *
 * Usage: node tools/make-test-rom.mjs [out.nes]
 */
import { writeFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { assemble } from "./asm6502.mjs";
import { buildFontChr } from "./font8x8.mjs";

const CODE = String.raw`
; ------------------------------------------------------------------ reset --
; NOTE: the NROM build keeps the code at $C000 (NROM-256 mirrors the last
; 16 KiB bank at $C000-$FFFF, so the vector table works there too).
.org $C000
RESET:
    SEI
    CLD
    LDX #$40
    STX $4017          ; APU frame IRQ off
    LDX #$FF
    TXS
    INX                ; X = 0
    STX $2000          ; NMI off
    STX $2001          ; rendering off
    STX $4010          ; DMC IRQ off

wait1:
    BIT $2002
    BPL wait1

clrmem:
    LDA #$00
    STA $0000,X
    STA $0100,X
    STA $0200,X
    STA $0300,X
    STA $0400,X
    STA $0500,X
    STA $0600,X
    STA $0700,X
    INX
    BNE clrmem

wait2:
    BIT $2002
    BPL wait2

; ------------------------------------------------------- upload CHR-RAM ----
    LDA #CHRDST_HI
    STA $2006
    LDA #$00
    STA $2006          ; VRAM address CHRDST_HI*256
    LDA #<CHRTILES
    STA $00
    LDA #>CHRTILES
    STA $01
    LDX #CHR_PAGES     ; pages of 256 bytes to copy
    LDY #$00
chrpage:
    LDA ($00),Y
    STA $2007
    INY
    BNE chrpage
    INC $01
    DEX
    BNE chrpage

; -------------------------------------------------------- clear nametable --
    LDA #$20
    STA $2006
    LDA #$00
    STA $2006
    LDA #$00
    LDX #$04
    LDY #$00
clrnt:
    STA $2007
    DEY
    BNE clrnt
    DEX
    BNE clrnt

; ---------------------------------------------------------------- headline --
    LDA #$20
    STA $2006
    LDA #$42
    STA $2006          ; row 4, column 2
    LDX #$00
line1:
    LDA TEXT1,X
    BEQ line1done
    STA $2007
    INX
    BNE line1
line1done:
    LDA #$20
    STA $2006
    LDA #$82
    STA $2006          ; row 8, column 2
    LDX #$00
line2:
    LDA TEXT2,X
    BEQ line2done
    STA $2007
    INX
    BNE line2
line2done:

; ---------------------------------------------------------------- palette --
    LDA #$3F
    STA $2006
    LDA #$00
    STA $2006
    LDA #$0F           ; backdrop: black
    STA $2007
    LDA #$30           ; text colour: white
    STA $2007
    STA $2007
    STA $2007

; ------------------------------------------------------------- start video --
    ; $2006 writes above also changed the nametable select bits in the "t"
    ; register, so rewrite $2000 to point back at nametable 0 before $2005.
    LDA #$80          ; NMI on, background pattern table 0, nametable 0
    STA $2000
    LDA #$00
    STA $2005
    STA $2005          ; scroll (0,0)
    LDA #$0E           ; background + sprites, no clipping
    STA $2001

main:
    JMP main           ; the NMI does all the work

; --------------------------------------------------------------------- NMI --
NMI:
    INC $10            ; bump frame counter, then return
    RTI
IRQ:
    RTI
`;

const TEXT1 = "GUN NAC - OFFLINE TEST ROM";
const TEXT2 = "EMULATOR OK";

/**
 * MMC3 (mapper 4) variant of the test ROM — the same mapper Gun Nac uses.
 * 128 KiB PRG in 8 banks; the code sits in the *last* bank, which MMC3 maps to
 * $E000-$FFFF without any bank switching, so a boot test exercises mapper 4
 * initialisation, PRG-RAM access and CHR-RAM upload.
 */
export function buildMmc3TestRom() {
  const chr = buildFontChr();
  // The shared CODE blob is assembled at $C000 for NROM. MMC3's fixed bank is
  // $E000, so re-home it before appending the data and vectors.
  const code = CODE.replace(".org $C000", ".org $E000");
  // MMC3's fixed bank at $E000 is only 8 KiB, so we cannot carry the full 8 KiB
  // font next to the code. Upload just tiles 32..95 (1 KiB) instead.
  const compactChr = chr.subarray(32 * 16, 96 * 16);
  const withChr = `${code}

CHRTILES:
    .res ${compactChr.length}

TEXT1:
    .byte "${TEXT1}", 0
TEXT2:
    .byte "${TEXT2}", 0

; ----------------------------------------------------------------- vectors --
.org $FFFA
    .word NMI
    .word RESET
    .word IRQ
`;

  const { bytes, symbols, imageBase } = assemble(withChr, {
    org: 0xe000,
    symbols: { CHRDST_HI: 0x02, CHR_PAGES: 4 }, // write tiles 32.. to $0200
  });
  if (imageBase !== 0xe000) {
    throw new Error(`MMC3 test ROM must start at $E000, got $${imageBase.toString(16)}`);
  }
  if (bytes.length > 8 * 1024) {
    throw new Error(`MMC3 fixed bank overflow: ${bytes.length} > 8192 bytes`);
  }
  const chrOffset = symbols.CHRTILES - imageBase;
  if (chrOffset + compactChr.length > 0xfffa - 0xe000) {
    throw new Error("MMC3 ROM: code + glyphs do not fit in the fixed bank");
  }
  const prg = new Uint8Array(128 * 1024);
  // A 16 KiB PRG bank covers $C000-$FFFF, so the $E000-$FFFF image lives in
  // the SECOND half of bank 7 at offset +8192. Bank 7 is hardwired into
  // $C000-$FFFF by MMC3 (and $E000-$FFFF is always bank 7).
  const FIXED_BANK_OFFSET = 7 * 16 * 1024 + 0x2000;
  prg.set(bytes, FIXED_BANK_OFFSET);
  prg.set(compactChr, FIXED_BANK_OFFSET + chrOffset);

  const header = new Uint8Array(16);
  header.set([0x4e, 0x45, 0x53, 0x1a]);
  header[4] = 8; // 8 x 16 KiB PRG = 128 KiB
  header[5] = 0; // CHR-RAM
  header[6] = 0x40; // mapper 4 low nibble, horizontal mirroring, no battery
  header[7] = 0;

  const rom = new Uint8Array(16 + prg.length);
  rom.set(header, 0);
  rom.set(prg, 16);
  return rom;
}

export function buildTestRom() {
  const chr = buildFontChr();
  const code = CODE;

  // CHRTILES must live after the code but before the vector table at $FFFA.
  // Put it right after the code, then re-assemble with the vectors last.
  // NROM-256 has a whole 16 KiB bank here, so the full 8 KiB font fits.
  const withChr = `${code}

CHRTILES:
    .res ${chr.length}

TEXT1:
    .byte "${TEXT1}", 0
TEXT2:
    .byte "${TEXT2}", 0

; ----------------------------------------------------------------- vectors --
.org $FFFA
    .word NMI
    .word RESET
    .word IRQ
`;

  const { bytes, symbols, imageBase } = assemble(withChr, {
    org: 0xc000,
    symbols: { CHRDST_HI: 0x00, CHR_PAGES: 0x20 },
  });
  if (process.env.DEBUG_ROM) {
    console.error("bytes", bytes.length, "symbols", {
      RESET: symbols.RESET.toString(16),
      CHRTILES: symbols.CHRTILES.toString(16),
      TEXT1: symbols.TEXT1.toString(16),
      TEXT2: symbols.TEXT2.toString(16),
      main: symbols.main.toString(16),
      NMI: symbols.NMI.toString(16),
    });
  }
  // 32 KiB PRG (NROM-256). The assembler image covers $C000-$FFFF, so it
  // lands in the upper 16 KiB of the ROM and the vector table at $FFFA is
  // reachable without mirroring tricks.
  const chrOffset = symbols.CHRTILES - 0xc000;
  if (chrOffset + chr.length > 0xfffa - 0xc000) {
    throw new Error(`Test ROM overflow: CHR at ${chrOffset.toString(16)}`);
  }
  const prg = new Uint8Array(32 * 1024);
  prg.set(bytes.subarray(0, 16 * 1024), 16 * 1024);
  if (process.env.DEBUG_ROM) {
    console.error("vectors @C000 image end:", Array.from(bytes.slice(-6)).map((b) => b.toString(16)));
    console.error("rom vec:", Array.from(prg.slice(0x7ffa)).map((b) => b.toString(16)));
  }
  prg.set(chr, 16 * 1024 + chrOffset);
  void copyText;

  const header = new Uint8Array(16);
  header.set([0x4e, 0x45, 0x53, 0x1a]); // "NES\x1a"
  header[4] = 2; // 2 x 16 KiB PRG = 32 KiB (NROM-256)
  header[5] = 0; // 0 CHR banks -> CHR-RAM
  header[6] = 0; // mapper 0, horizontal mirroring
  header[7] = 0;

  const rom = new Uint8Array(16 + prg.length);
  rom.set(header, 0);
  rom.set(prg, 16);
  return rom;
}

function copyText(prg, text, address, org) {
  const base = address - org;
  for (let i = 0; i < text.length; i++) prg[base + i] = text.charCodeAt(i);
  prg[base + text.length] = 0;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const outPath = process.argv[2] || "test/fixtures/test.nes";
  const rom = buildTestRom();
  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, rom);
  console.log(`Wrote ${outPath} (${rom.length} bytes)`);
}
